import os
from typing import Any, Dict, List, Optional, Tuple

import requests

GEMINI_API_URL = "https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent"


def _extract_text_response(data: Dict[str, Any]) -> str:
    candidates = data.get("candidates") or []
    if not candidates:
        raise ValueError("No candidates returned by Gemini API.")
    content = candidates[0].get("content") or {}
    parts = content.get("parts") or []
    texts = []
    for part in parts:
        text = part.get("text")
        if text:
            texts.append(text)
    if not texts:
        raise ValueError("No text content returned by Gemini API.")
    return "\n".join(texts).strip()


def _build_prompt(document_text: str, required_fields: List[str], confidence_threshold: float) -> str:
    fields_json = ", ".join(required_fields)
    return (
        "You are a document extraction validator.\n"
        "Return ONLY valid JSON with this schema:\n"
        "{\n"
        '  "fields": { "<field_name>": {"value": string|null, "confidence": number} },\n'
        '  "missing_fields": [string],\n'
        '  "low_confidence_fields": [string],\n'
        '  "is_valid": boolean\n'
        "}\n\n"
        f"Required fields: [{fields_json}]\n"
        f"Confidence threshold: {confidence_threshold}\n\n"
        "Rules:\n"
        "- Every required field must appear in fields.\n"
        "- confidence must be a number between 0 and 1.\n"
        "- missing_fields includes any required field with null/empty value.\n"
        "- low_confidence_fields includes any required field with confidence below threshold.\n"
        "- is_valid is true only if there are no missing_fields and no low_confidence_fields.\n\n"
        f"Document text:\n{document_text}"
    )


def _post_to_gemini(prompt: str, api_key: str, timeout: int = 60) -> Dict[str, Any]:
    url = f"{GEMINI_API_URL}?key={api_key}"
    payload = {
        "contents": [
            {
                "parts": [
                    {"text": prompt}
                ]
            }
        ],
        "generationConfig": {
            "temperature": 0.0,
            "responseMimeType": "application/json"
        }
    }
    resp = requests.post(url, json=payload, timeout=timeout)
    resp.raise_for_status()
    return resp.json()


def _parse_json_like(text: str) -> Dict[str, Any]:
    import json

    try:
        return json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Model did not return valid JSON: {exc}") from exc


def validate_structured_fields(
    document_text: str,
    required_fields: List[str],
    confidence_threshold: float = 0.8,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Validates required structured fields and confidence scores using Google Gemini API.

    Returns a dict with:
      - fields: extracted field metadata
      - missing_fields: list of missing required fields
      - low_confidence_fields: list of required fields below threshold
      - is_valid: boolean
    """
    if not document_text or not document_text.strip():
        raise ValueError("document_text is required.")
    if not required_fields:
        raise ValueError("required_fields must not be empty.")
    if not 0.0 <= confidence_threshold <= 1.0:
        raise ValueError("confidence_threshold must be between 0 and 1.")

    api_key = api_key or os.getenv("GEMINI_API_KEY")
    if not api_key:
        raise ValueError("Missing Gemini API key. Set GEMINI_API_KEY or pass api_key.")

    prompt = _build_prompt(document_text, required_fields, confidence_threshold)
    data = _post_to_gemini(prompt, api_key=api_key)
    text = _extract_text_response(data)
    result = _parse_json_like(text)

    fields = result.get("fields")
    missing_fields = result.get("missing_fields")
    low_confidence_fields = result.get("low_confidence_fields")
    is_valid = result.get("is_valid")

    if not isinstance(fields, dict):
        raise ValueError("Invalid response: fields must be an object.")
    if not isinstance(missing_fields, list):
        raise ValueError("Invalid response: missing_fields must be a list.")
    if not isinstance(low_confidence_fields, list):
        raise ValueError("Invalid response: low_confidence_fields must be a list.")
    if not isinstance(is_valid, bool):
        raise ValueError("Invalid response: is_valid must be a boolean.")

    required_set = set(required_fields)
    returned_set = set(fields.keys())
    if not required_set.issubset(returned_set):
        raise ValueError("Invalid response: not all required fields were returned.")

    normalized_missing = []
    normalized_low = []

    for field in required_fields:
        info = fields.get(field) or {}
        value = info.get("value")
        confidence = info.get("confidence")

        if value is None or (isinstance(value, str) and not value.strip()):
            normalized_missing.append(field)

        if not isinstance(confidence, (int, float)) or not 0.0 <= float(confidence) <= 1.0:
            raise ValueError(f"Invalid response: confidence for '{field}' must be between 0 and 1.")

        if float(confidence) < confidence_threshold:
            normalized_low.append(field)

    normalized_is_valid = not normalized_missing and not normalized_low

    return {
        "fields": fields,
        "missing_fields": normalized_missing,
        "low_confidence_fields": normalized_low,
        "is_valid": normalized_is_valid and bool(is_valid),
    }
